// Met en forme l'alerte — un email lisible en 5 secondes.
const j = items[0].json || {};
const wf = j.workflow || {};
const ex = j.execution || {};
const err = ex.error || {};
const lines = [
  `Workflow : ${wf.name || 'inconnu'}`,
  `Nœud     : ${ex.lastNodeExecuted || err.node?.name || 'inconnu'}`,
  `Erreur   : ${err.message || 'sans message'}`,
  `Quand    : ${new Date().toLocaleString('fr-FR')}`,
  '',
  ex.url ? `Voir l'exécution : ${ex.url}` : `Exécution #${ex.id || '?'} — ouvre n8n → Executions.`,
  '',
  'Réflexe : ouvre l\'exécution, lis la sortie du nœud rouge, corrige (credential expiré ? Sheet renommé ? Ollama éteint ?), puis « Retry ».'
];
return [{ json: {
  subject: `⚠️ ALPHA OS — « ${wf.name || 'workflow'} » a échoué`,
  body: lines.join('\n'),
} }];
